// Name: Lambda
// ID: cubesterLambda
// Description: Make and use anonymous scripts.
// By: CubesterYT <https://scratch.mit.edu/users/CubesterYT/>

// Version V.1.0.0

(function (Scratch) {
  "use strict";

  const icon =
    "data:image/png;base64,";

  const compileArguments = (args) =>
    Object.keys(args)
      .filter((name) => /^ARGS_\d+_ARG$/.test(name))
      .sort((a, b) => Number(a.slice(5, -4)) - Number(b.slice(5, -4)))
      .map((name) => args[name])
      .join(",");

  class Lambda {
    getInfo() {
      return {
        id: "cubesterLambda",
        name: Scratch.translate("Lambda"),
        color1: "#FF894D",
        menuIconURI: icon,
        docsURI: "https://extensions.nitrobolt.org/CubesterYT/Lambda",

        blocks: [
          {
            opcode: "lambda",
            func: "compilerOnly",
            text: Scratch.translate("new function [ARGS]"),
            blockType: Scratch.BlockType.OBJECT,
            branchCount: 1,
            arguments: {
              ARGS: {
                type: Scratch.ArgumentType.ARRAY,
                shadow: "lambdaArgs",
              },
            },
            compiler: {
              input: this.compileLambda,
              stack: null,
            },
          },
          {
            opcode: "lambdaArgs",
            func: "compilerOnly",
            text: Scratch.translate("arguments"),
            blockType: Scratch.BlockType.ARRAY,
            duplicateOnDrag: true,
            hideFromPalette: true,
            compiler: this.compileLambdaArgs,
          },

          "---",

          {
            opcode: "executeCommand",
            func: "compilerOnly",
            text: Scratch.translate("execute [LAMBDA] with [ARGS]"),
            blockType: Scratch.BlockType.COMMAND,
            arguments: {
              LAMBDA: {
                type: Scratch.ArgumentType.OBJECT,
              },
              ARGS: {
                type: Scratch.ArgumentType.EXTENDABLE,
                text: Scratch.translate("[ARG]"),
                arguments: {
                  ARG: {
                    type: Scratch.ArgumentType.STRING,
                    defaultValue: "",
                  },
                },
              },
            },
            compiler: this.compileExecuteCommand,
          },
          {
            opcode: "executeReport",
            func: "compilerOnly",
            text: Scratch.translate("execute [LAMBDA] with [ARGS]"),
            blockType: Scratch.BlockType.REPORTER,
            allowDropAnywhere: true,
            arguments: {
              LAMBDA: {
                type: Scratch.ArgumentType.OBJECT,
              },
              ARGS: {
                type: Scratch.ArgumentType.EXTENDABLE,
                text: Scratch.translate("[ARG]"),
                arguments: {
                  ARG: {
                    type: Scratch.ArgumentType.STRING,
                    defaultValue: "",
                  },
                },
              },
            },
            compiler: this.compileExecuteReport,
          },
        ],
      };
    }

    compileLambda(_, util) {
      const lambda = util.compileFunction(
        1,
        ["lambdaArguments", "target", "runtime", "stage"],
        '""'
      );
      return `(${lambda})`;
    }

    compileLambdaArgs() {
      return `(typeof lambdaArguments === "undefined" ? [] : lambdaArguments)`;
    }

    compileExecuteCommand(args) {
      const lambdaArguments = compileArguments(args);
      return `yield* (function* (lambda) {
        if (typeof lambda !== "function") return;
        const result = lambda([${lambdaArguments}], target, runtime, stage);
        if (result && typeof result.next === "function") yield* result;
      })(${args.LAMBDA});\n`;
    }

    compileExecuteReport(args) {
      const lambdaArguments = compileArguments(args);
      return `(yield* (function* (lambda) {
        if (typeof lambda !== "function") return "";
        const result = lambda([${lambdaArguments}], target, runtime, stage);
        if (!result || typeof result.next !== "function") return "";
        return yield* result;
      })(${args.LAMBDA}))`;
    }

    compilerOnly() {
      throw new Error("The Lambda extension requires the compiler");
    }
  }

  Scratch.extensions.register(new Lambda());
})(Scratch);
